def calculate_variance(nums: list[float]) -> float:
    """Calculate population variance of numbers."""
    if not nums:
        return 0.0
    mean = sum(nums) / len(nums)
    sum_diffs = sum((x - mean) ** 2 for x in nums)
    return sum_diffs / len(nums)

